def gh(args, _input=None):
    cmd = ["gh", *args]
    r = subprocess.run(cmd, capture_output=True, text=True, input=_input, encoding="utf-8", errors="replace")
    if r.returncode != 0:
        print("GH ERR:", " ".join(args[:4]), r.stderr[-800:], file=sys.stderr)
    return r

q = """
query {
  repository(owner: "xcoder-es", name: "nomos") {
    pullRequest(number: %d) {
      title
      body
      reviewThreads(first: 20) {
        nodes {
          id
          isResolved
          path
          line
          comments(first: 10) {
            nodes { databaseId body author { login } }
          }
        }
      }
    }
  }
}
""" % PR

r = gh(["api", "graphql", "-f", "query=" + q])
data = json.loads(r.stdout)["data"]["repository"]["pullRequest"]
print("TITLE:", data["title"])
print("BODY:", (data.get("body") or "").replace("\n", " ")[:160].strip())
print()
for t in data["reviewThreads"]["nodes"]:
