def gh(args, data=None):
    cmd = ["gh"] + args
    if data is not None:
        cmd += ["--input", "-"]
        r = subprocess.run(cmd, capture_output=True, text=True, input=json.dumps(data),
                           encoding="utf-8", errors="replace")
    else:
        r = subprocess.run(cmd, capture_output=True, text=True, encoding="utf-8", errors="replace")
    if r.returncode != 0:
        print("GH ERR:", " ".join(args[:3]), r.stderr[-500:])
    return r

