def _parse_json_docs(text):
    """Parse consecutive JSON documents (compact lines or pretty multi-line)."""
    decoder = json.JSONDecoder()
    idx = 0
    docs = []
    while idx < len(text):
        while idx < len(text) and text[idx] in " \t\r\n":
            idx += 1
        if idx >= len(text):
            break
        doc, idx = decoder.raw_decode(text, idx)
        docs.append(doc)
    return docs


